<script lang="ts">
  import {onMount} from 'svelte';
  import RecordedHarnessArm from '$lib/components/RecordedHarnessArm.svelte';
  import type {RecordedComparison} from '$lib/workbench/recorded';
  let data=$state.raw<RecordedComparison|null>(null),error=$state('');
  let selectedFile=$state('skills/mojo-verify/SKILL.md');
  const change=$derived(data?.changes.find(f=>f.path===selectedFile));
  onMount(()=>{
    const c=new AbortController();
    void (async()=>{try{
      const r=await fetch('/api/workbench-recorded',{signal:c.signal}),d=await r.json();
      if(!r.ok)throw Error(d.error??'Recorded comparison unavailable.');data=d;
    }catch(e){if(!c.signal.aborted)error=e instanceof Error?e.message:'Recorded comparison unavailable.';}})();
    return()=>c.abort();
  });
</script>

<svelte:head><title>Base | Improved | Changes · Glimmer Lab</title><meta name="description" content="A read-only comparison of two saved Harness² rollouts. This view makes no model calls."/></svelte:head>
<div class="recorded-workbench">
  <nav class="workbench-switch" aria-label="Workbench views"><a href="/workbench/recorded" aria-current="page">Recorded comparison</a><a href="/workbench">Live profile editor ↗</a></nav>
  <header class="recorded-heading"><div><span class="recording-label">RECORDED RUN <span>· No live generation</span></span><h1>Same model. Different harness.</h1><p>Harness² changes the instructions, skills and tools around Glimmer—not its weights.</p></div>{#if data}<div class="result-count"><span>Recorded heldout passes</span><strong>{data.results.base}<small>/{data.results.total}</small> <i>→</i> {data.results.improved}<small>/{data.results.total}</small></strong><span>Base → primary improved harness</span></div>{/if}</header>
  {#if error}<div class="recorded-error" role="alert"><h2>Recording unavailable</h2><p>{error}</p><p>No result or substitute has been generated. This view never runs a model.</p></div>
  {:else if !data}<p class="recorded-loading" role="status">Checking the saved evidence’s file identities…</p>
  {:else}
    <section class="result-context" aria-label="All ten heldout task results"><div class="strip-heading"><h2>All ten tasks, same recorded comparison</h2><span>Top: Base · Bottom: Improved · Selected example outlined</span></div><ol class="task-strip">{#each data.tasks as t,i}<li class:selected={t.id===data.task}><span class="task-number">{String(i+1).padStart(2,'0')}</span><span class="task-name">{t.id.replace(/^(generics|simd)-/,'').replaceAll('-',' ')}<small>{t.id.startsWith('generics')?'Generics':'SIMD'}</small></span><span class="task-status" class:pass={t.base.passed} title={t.base.rollout==='failed'?`${t.base.modelCalls} model calls; no delivered program. Reason: ${t.base.reason??'not recorded'}`:'External compile/run grade'} aria-label={`${t.id} base ${t.base.passed?'pass':t.base.rollout==='failed'?'failed rollout':'fail'}`}>{t.base.passed?'PASS':t.base.rollout==='failed'?'NO PROGRAM':'FAIL'}</span><span class="task-status" class:pass={t.improved.passed} title={t.improved.rollout==='failed'?`${t.improved.modelCalls} model calls; no delivered program. Reason: ${t.improved.reason??'not recorded'}`:'External compile/run grade'} aria-label={`${t.id} improved ${t.improved.passed?'pass':t.improved.rollout==='failed'?'failed rollout':'fail'}`}>{t.improved.passed?'PASS':t.improved.rollout==='failed'?'NO PROGRAM':'FAIL'}</span></li>{/each}</ol>
    <p class="strip-caveat">One rollout per task per harness. No-program rollouts count as failures, not missing results. This is a selected demonstration, not a reliability estimate.</p></section>
    <section class="task-brief"><div><span class="small-label">SELECTED TASK · {data.run}</span><h2>Find the largest element</h2></div><details><summary>Exact task &amp; settings</summary><pre>{data.base.prompt}</pre><p>Executor: {data.model} · temperature {data.temperature} · thinking {data.thinking} · {data.maxModelCalls} model-call cap. Both arms bind the same executor runtime and task identity.</p></details></section>
    <div class="comparison-grid"><RecordedHarnessArm arm={data.base}/><RecordedHarnessArm arm={data.improved}/>
      <aside class="harness-changes" aria-label="Recorded harness changes"><span class="small-label">WHAT WAS CHANGED</span><h2>Changes</h2><p>Exact frozen files—not a live edit or an automatically inferred explanation.</p>
        <div class="changes-count">{data.changes.filter(f=>f.kind==='added').length} added · {data.changes.filter(f=>f.kind==='changed').length} changed · {data.changes.filter(f=>f.kind==='unchanged').length} unchanged · {data.changes.filter(f=>f.kind==='removed').length} removed</div>
        <label class="file-selector">Harness file<select aria-label="Harness file" bind:value={selectedFile}>{#each data.changes as f}<option value={f.path}>{f.kind} · {f.path}</option>{/each}</select></label>
        {#if change}<h3 class="file-path">{change.path}</h3><span class="change-kind">{change.kind}</span><div class="file-difference">{#each ['base','improved'] as side}<details open={side==='improved'}><summary>{side==='base'?'Base':'Improved'} file {change[side as 'base'|'improved']?'':'· absent'}</summary>{#if change[side as 'base'|'improved']}<pre aria-label={`${side} harness file`}>{change[side as 'base'|'improved']!.text||'(Empty file)'}</pre><p class="file-hash">SHA-256 {change[side as 'base'|'improved']!.sha256}</p>{:else}<p>Not present in this frozen harness.</p>{/if}</details>{/each}</div>{/if}
        <div class="reading-note"><h3>What this example actually shows</h3><p>The improved rollout receives three compiler diagnostics and edits the source. Its last self-check says <strong>“compiled, but no code ran.”</strong> The separate external grader then runs the submitted program and passes it.</p><p>Compiler feedback is visible here. This pair does not isolate which harness change caused the improvement.</p></div>
      </aside>
    </div>
    <footer class="recorded-disclosures"><h2>Reading this recording honestly</h2><div class="disclosure-grid"><p><strong>Recorded, not replayed live.</strong> Manual controls step through all saved tool exchanges. Commands, extensions and source are inert text; nothing here executes. Tool outputs include the harness’s recorded reminder messages. Streamed token fragments are not animated.</p><p><strong>Different roles.</strong> Claude/Opus was the harness improver; Glimmer executed these tasks. Compile/run tests decide the pass count. Muse’s quality opinions are separate. The primary is fixed-dot-product’s agg1, selected by the registered fallback, not by picking the highest heldout score.</p><p><strong>Small, selected evidence.</strong> Ten tasks, one rollout each. The run’s cross-run determinism check failed, despite greedy decoding. Opening or importing a harness does not reproduce this result or train Glimmer.</p><p><strong>The live editor is a different delivery path.</strong> The importer inlines skill text, omits executable helpers and extensions, and starts with tools off. This recording shows the original on-demand skills and historical helper calls. A live adaptation must be disclosed separately.</p></div>
      <details><summary>Bound evidence inventory · {Object.keys(data.inputs).length} files</summary><p>Local pinned source: nomos_data/harness2-runs/mojo-glimmer-20261031. Captures are not bundled into the application. Changed or missing input refuses the whole view.</p><pre>{Object.entries(data.inputs).map(([file,hash])=>`${hash}  ${file}`).join('\n')}</pre></details>
    </footer>
  {/if}
</div>

